    "audioNormalUrl": "https://pilates-english-teaching-book.vercel.app/%EC%98%81%EC%96%B4_%EB%B0%9C%EC%9D%8C/30b2347acbb45c7f4268.mp3",
    "audioSlowUrl": "https://pilates-english-teaching-book.vercel.app/%EC%98%81%EC%96%B4_%EB%B0%9C%EC%9D%8C/30b2347acbb45c7f4268.mp3",
    "audioPlaceholder": false
