    "audioNormalUrl": "https://pilates-english-teaching-book.vercel.app/%EC%98%81%EC%96%B4_%EB%B0%9C%EC%9D%8C/ffa6e04160a45f0fd9cb.mp3",
    "audioSlowUrl": "https://pilates-english-teaching-book.vercel.app/%EC%98%81%EC%96%B4_%EB%B0%9C%EC%9D%8C/ffa6e04160a45f0fd9cb.mp3",
